//! Linux `stat` and `statx` metadata for the synthetic surface and the staged root tree.
//!
//! The values are deterministic: the staged tree supplies size and permission bits, the synthetic
//! procfs/sysfs files derive their size from the generated bytes, and every path gets a stable
//! inode from an FNV-1a hash. Timestamps are zero; the personality has no clock source for file
//! times yet (documented in `docs/linux-syscalls.md`).

use alloc::vec::Vec;

use raven_abi::errno::Errno;
use raven_linux_abi::flags::stat::{S_IFCHR, S_IFDIR, S_IFLNK, S_IFREG};

use crate::procfs::{self, Resource};
use crate::table::{FileKind, LinuxProcess};

/// Metadata for one Linux path or descriptor.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Meta {
    /// `S_IF*` type and permission bits.
    pub mode: u32,
    /// File size in bytes.
    pub size: u64,
    /// Inode number.
    pub ino: u64,
    /// Link count.
    pub nlink: u64,
    /// `st_rdev` (zero for everything this server serves).
    pub rdev: u64,
}

impl Meta {
    /// Metadata for a regular file.
    #[must_use]
    pub fn file(size: u64, ino: u64) -> Self {
        Self {
            mode: S_IFREG | 0o644,
            size,
            ino,
            nlink: 1,
            rdev: 0,
        }
    }

    /// Metadata for a directory.
    #[must_use]
    pub fn directory(ino: u64) -> Self {
        Self {
            mode: S_IFDIR | 0o755,
            size: 4096,
            ino,
            nlink: 2,
            rdev: 0,
        }
    }

    /// Metadata for a symlink.
    #[must_use]
    pub fn symlink(size: u64, ino: u64) -> Self {
        Self {
            mode: S_IFLNK | 0o777,
            size,
            ino,
            nlink: 1,
            rdev: 0,
        }
    }

    /// Metadata for a character device (the standard descriptors).
    #[must_use]
    pub fn character(ino: u64) -> Self {
        Self {
            mode: S_IFCHR | 0o600,
            size: 0,
            ino,
            nlink: 1,
            rdev: 0,
        }
    }

    /// `st_blksize` reported for every node.
    #[must_use]
    pub fn blksize(&self) -> u64 {
        4096
    }

    /// `st_blocks`: 512-byte units, rounded up.
    #[must_use]
    pub fn blocks(&self) -> u64 {
        self.size.saturating_add(511) / 512
    }
}

/// Resolve the metadata of one absolute path.
pub fn path_meta(process: &LinuxProcess, path: &[u8]) -> Result<Meta, Errno> {
    if let Some(node) = process.root().lookup(path) {
        return Ok(Meta {
            mode: node.mode,
            size: node.size,
            ino: node.ino,
            nlink: if node.is_dir() { 2 } else { 1 },
            rdev: 0,
        });
    }
    match procfs::lookup(process, path)? {
        Resource::File(bytes) => Ok(Meta::file(bytes.len() as u64, ino(path))),
        Resource::Directory(_) => Ok(Meta::directory(ino(path))),
        Resource::Symlink(target) => Ok(Meta::symlink(target.len() as u64, ino(path))),
    }
}

/// Resolve the metadata of one open descriptor.
pub fn file_meta(process: &LinuxProcess, fd: i32) -> Result<Meta, Errno> {
    if fd < 0 {
        return Err(Errno::EBADF);
    }
    if (0..=2).contains(&fd) {
        return Ok(Meta::character(ino(b"stdio")));
    }
    let Some(file) = process.file(fd) else {
        return Err(Errno::EBADF);
    };
    Ok(match &file.kind {
        FileKind::Regular(bytes) => Meta::file(bytes.len() as u64, ino(&file.path)),
        FileKind::Directory(_) => Meta::directory(ino(&file.path)),
        FileKind::Symlink(target) => Meta::symlink(target.len() as u64, ino(&file.path)),
        FileKind::Remote(_) => Meta::file(0, ino(&file.path)),
    })
}

/// Serialize `meta` as the x86-64 `struct stat` (144 bytes).
#[must_use]
pub fn stat_bytes(meta: &Meta) -> Vec<u8> {
    let mut bytes = [0u8; 144];
    put_u64(&mut bytes, 0, 0); // st_dev
    put_u64(&mut bytes, 8, meta.ino);
    put_u64(&mut bytes, 16, meta.nlink);
    put_u32(&mut bytes, 24, meta.mode);
    put_u32(&mut bytes, 28, 0); // st_uid
    put_u32(&mut bytes, 32, 0); // st_gid
    put_u32(&mut bytes, 36, 0); // __pad0
    put_u64(&mut bytes, 40, meta.rdev);
    put_u64(&mut bytes, 48, meta.size);
    put_u64(&mut bytes, 56, meta.blksize());
    put_u64(&mut bytes, 64, meta.blocks());
    // st_atime, st_mtime, st_ctime and their nanoseconds stay zero.
    bytes.to_vec()
}

/// Serialize `meta` as the x86-64 `struct statx` (256 bytes) with `mask`.
#[must_use]
pub fn statx_bytes(meta: &Meta, mask: u32) -> Vec<u8> {
    const BASIC_STATS: u32 = 0x7ff;
    let mask = mask & BASIC_STATS;
    let mut bytes = [0u8; 256];
    put_u32(&mut bytes, 0, mask);
    put_u32(&mut bytes, 4, meta.blksize() as u32);
    put_u64(&mut bytes, 8, 0); // attributes
    put_u32(&mut bytes, 16, meta.nlink as u32);
    put_u32(&mut bytes, 20, 0); // uid
    put_u32(&mut bytes, 24, 0); // gid
    put_u32(&mut bytes, 28, meta.mode & 0xffff);
    put_u64(&mut bytes, 32, meta.ino);
    put_u64(&mut bytes, 40, meta.size);
    put_u64(&mut bytes, 48, meta.blocks());
    put_u64(&mut bytes, 56, 0); // attributes mask
    // stx_atime/btime/ctime/mtime at 64/80/96/112 stay zero.
    put_u32(&mut bytes, 128, (meta.rdev >> 32) as u32); // rdev major
    put_u32(&mut bytes, 132, (meta.rdev & 0xffff_ffff) as u32); // rdev minor
    bytes.to_vec()
}

/// Stable non-zero inode for a path from FNV-1a.
fn ino(path: &[u8]) -> u64 {
    let mut hash: u64 = 0xcbf2_9ce4_8422_2325;
    for byte in path {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
    }
    hash.max(1)
}

fn put_u32(bytes: &mut [u8], offset: usize, value: u32) {
    if let Some(slot) = bytes.get_mut(offset..offset + 4) {
        slot.copy_from_slice(&value.to_le_bytes());
    }
}

fn put_u64(bytes: &mut [u8], offset: usize, value: u64) {
    if let Some(slot) = bytes.get_mut(offset..offset + 8) {
        slot.copy_from_slice(&value.to_le_bytes());
    }
}

